    const pdfExportAbs = `${basePath}/${targets[1].rel}`;
    plugin.settings.ocrScriptPath = layoutEngineAbs;
    plugin.settings.mergeScriptPath = pdfExportAbs;
    plugin.settings.pdfExportScriptPath = pdfExportAbs;
    await plugin.saveSettings();
    new import_obsidian.Notice("Python scripts installed into the plugin folder.");
    return { layoutEngineAbs, pdfExportAbs };
